scripts.onUpdate:
function getTilemap(entity) {
  const direct = entity && entity.getComponent && entity.getComponent('Tilemap2DComponent');
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === 'Tilemap2DComponent' || String(item.UniqueSymbol) === 'Symbol(Tilemap2DComponent)')) return item;
  }
  return null;
}

function getCanvasText(entity) {
  const direct = entity && entity.getComponent && entity.getComponent('CanvasTextComponent');
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === 'CanvasTextComponent' || String(item.UniqueSymbol) === 'Symbol(CanvasTextComponent)')) return item;
  }
  return null;
}

const config = api.read.data() || {};
const boardEntity = api.read && api.read.find('Snake Board');
const board = getTilemap(boardEntity);
const scoreTextEntity = api.read && api.read.find('Snake Score Text');
const statusTextEntity = api.read && api.read.find('Snake Status Text');
const hintTextEntity = api.read && api.read.find('Snake Hint Text');

if (!board) {
  api.debug.console.warn('Snake Starter requires Snake Board with Tilemap2DComponent.');
  return;
}

const state = component.state || (component.state = {});
const rows = Number(config.rows || board.rows || 20);
const cols = Number(config.columns || board.columns || 20);
const palette = config.paletteIndex || { empty: 1, emptyAlt: 5, body: 2, head: 3, food: 4 };

function reset() {
  const cx = Math.floor(cols / 2);
  const cy = Math.floor(rows / 2);
  state.snake = [
    { x: cx + 1, y: cy },
    { x: cx, y: cy },
    { x: cx - 1, y: cy }
  ];
  state.direction = { x: 1, y: 0 };
  state.queuedDirection = { x: 1, y: 0 };
  state.score = 0;
  state.best = Math.max(Number(state.best || 0), Number(config.best || 0));
  state.phase = 'playing';
  state.stepTimer = 0;
  state.food = spawnFood();
}

function sameCell(a, b) {
  return a && b && a.x === b.x && a.y === b.y;
}

function containsSnake(cell, body) {
  return body.some(function (part) { return sameCell(part, cell); });
}

function spawnFood() {
  const free = [];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const cell = { x: x, y: y };
      if (!containsSnake(cell, state.snake || [])) free.push(cell);
    }
  }
  return free.length ? free[Math.floor(Math.random() * free.length)] : null;
}

function queueDirection(next) {
  if (!next || state.phase !== 'playing') return;
  const current = state.direction || { x: 1, y: 0 };
  if (next.x + current.x === 0 && next.y + current.y === 0) return;
  state.queuedDirection = next;
}

function stepSnake() {
  if (state.phase !== 'playing') return;
  state.direction = state.queuedDirection || state.direction || { x: 1, y: 0 };
  const head = state.snake[0];
  const nextHead = { x: head.x + state.direction.x, y: head.y + state.direction.y };
  const eats = sameCell(nextHead, state.food);
  const collisionBody = eats ? state.snake : state.snake.slice(0, -1);
  const hitWall = nextHead.x < 0 || nextHead.y < 0 || nextHead.x >= cols || nextHead.y >= rows;
  if (hitWall || containsSnake(nextHead, collisionBody)) {
    state.phase = 'gameover';
    state.best = Math.max(state.best, state.score);
    return;
  }
  state.snake.unshift(nextHead);
  if (eats) {
    state.score += 1;
    state.best = Math.max(state.best, state.score);
    state.food = spawnFood();
    if (!state.food) state.phase = 'won';
  } else {
    state.snake.pop();
  }
}

function setTilemapTransform(entity, x, y) {
  const transform = entity && entity.getComponent && entity.getComponent('Transform2D');
  if (!transform) return;
  transform.x = x;
  transform.y = y;
}

function layoutTilemap(tilemap, cellWidth, cellHeight, gap) {
  if (!tilemap) return;
  tilemap.cellWidth = cellWidth;
  tilemap.cellHeight = cellHeight;
  tilemap.gap = gap;
}

function setTextBox(entity, value, x, y, width, height, fontSize, color, align) {
  if (!entity) return;
  const transform = entity.getComponent && entity.getComponent('Transform2D');
  if (transform) {
    transform.x = x;
    transform.y = y;
  }
  const text = getCanvasText(entity);
  if (!text) return;
  text.text = String(value || '');
  const style = text.style || {};
  const next = {
    ...style,
    width: Math.max(1, Math.floor(width)),
    height: Math.max(1, Math.floor(height)),
    resolutionScale: Number(config.textResolutionScale || 2),
    backgroundColor: 'rgba(255,255,255,0)',
    borderWidth: 0,
    padding: 0,
    textAlign: align || 'center',
    verticalAlign: 'middle',
    fontSize: Math.max(8, Math.floor(fontSize)),
    fontFamily: 'system-ui, sans-serif',
    fontWeight: '800',
    lineHeight: 1.15,
    color: color || '#e5e7eb',
    whiteSpace: 'pre-line'
  };
  if (style.width !== next.width || style.height !== next.height || style.fontSize !== next.fontSize || style.color !== next.color || style.textAlign !== next.textAlign || style.resolutionScale !== next.resolutionScale) {
    text.style = next;
  }
}

function updateLayout() {
  const canvas = document.getElementById('player-canvas');
  const width = Math.max(1, canvas && canvas.clientWidth || window.innerWidth || 390);
  const height = Math.max(1, canvas && canvas.clientHeight || window.innerHeight || 844);
  const portrait = height >= width;
  const margin = portrait ? 18 : 34;
  const verticalReserve = portrait ? 210 : 96;
  const sideReserve = portrait ? margin * 2 : Math.min(260, Math.max(180, width * 0.24));
  const cell = Math.max(12, Math.floor(Math.min(
    (width - sideReserve) / cols,
    (height - verticalReserve) / rows,
    portrait ? 24 : 30
  )));
  const gap = Math.max(1, Math.floor(cell * 0.08));
  const boardWidth = cols * cell;
  const boardHeight = rows * cell;
  const boardX = portrait ? -boardWidth / 2 : -boardWidth / 2 - Math.min(96, width * 0.08);
  const boardY = portrait ? -boardHeight / 2 - 6 : -boardHeight / 2;
  state.layout = { boardX: boardX, boardY: boardY, cell: cell, rows: rows, cols: cols };
  layoutTilemap(board, cell, cell, gap);
  setTilemapTransform(boardEntity, boardX, boardY);

  const panelWidth = portrait ? Math.min(width - 36, Math.max(260, boardWidth)) : Math.min(220, Math.max(170, width * 0.18));
  const panelHeight = Math.max(26, Math.floor(cell * 1.35));
  const font = Math.max(13, Math.floor(cell * 0.62));
  const scoreValue = 'SCORE ' + state.score + '   BEST ' + state.best;
  if (portrait) {
    setTextBox(scoreTextEntity, scoreValue, -panelWidth / 2, boardY + boardHeight + 16, panelWidth, panelHeight, font, '#e5e7eb');
    setTextBox(statusTextEntity, statusLabel(), -panelWidth / 2, boardY + boardHeight + 18 + panelHeight, panelWidth, panelHeight, font, statusColor());
    setTextBox(hintTextEntity, 'Arrow keys / WASD / swipe', -panelWidth / 2, boardY - panelHeight - 14, panelWidth, panelHeight, Math.max(12, Math.floor(font * 0.82)), '#94a3b8');
  } else {
    const x = boardX + boardWidth + 34;
    setTextBox(scoreTextEntity, 'SCORE\n' + state.score + '\nBEST ' + state.best, x, boardY + boardHeight - panelHeight * 3, panelWidth, panelHeight * 3, font, '#e5e7eb', 'left');
    setTextBox(statusTextEntity, statusLabel(), x, boardY + boardHeight - panelHeight * 4.4, panelWidth, panelHeight, font, statusColor(), 'left');
    setTextBox(hintTextEntity, 'Arrow keys\nWASD\nSwipe\nR restart', x, boardY + 6, panelWidth, panelHeight * 4, Math.max(12, Math.floor(font * 0.78)), '#94a3b8', 'left');
  }
}

function statusLabel() {
  if (state.phase === 'won') return 'Board cleared! Press R';
  if (state.phase === 'gameover') return 'Game Over - Press R';
  return 'Eat food and keep moving';
}

function statusColor() {
  if (state.phase === 'won') return '#22c55e';
  if (state.phase === 'gameover') return '#f87171';
  return '#a7f3d0';
}

function draw() {
  updateLayout();
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      board.setCell(x, rows - 1 - y, (x + y) % 2 === 0 ? palette.empty : palette.emptyAlt);
    }
  }
  if (state.food) board.setCell(state.food.x, rows - 1 - state.food.y, palette.food);
  for (let i = state.snake.length - 1; i >= 0; i--) {
    const part = state.snake[i];
    board.setCell(part.x, rows - 1 - part.y, i === 0 ? palette.head : palette.body);
  }
}

function installPointerInput() {
  const canvas = document.getElementById('player-canvas');
  if (!canvas || !canvas.addEventListener) return;
  if (state.pointerReady && state.pointerCanvas === canvas) return;
  if (state.pointerCanvas && state.pointerDownHandler && state.pointerUpHandler && state.pointerCanvas.removeEventListener) {
    state.pointerCanvas.removeEventListener('pointerdown', state.pointerDownHandler);
    state.pointerCanvas.removeEventListener('pointerup', state.pointerUpHandler);
  }
  state.pointerDownHandler = function (event) {
    state.pointerStart = { x: event.clientX, y: event.clientY };
  };
  state.pointerUpHandler = function (event) {
    if (!state.pointerStart) return;
    const dx = event.clientX - state.pointerStart.x;
    const dy = event.clientY - state.pointerStart.y;
    state.pointerStart = null;
    const threshold = Number(config.swipeThreshold || 22);
    if (Math.max(Math.abs(dx), Math.abs(dy)) < threshold) return;
    if (Math.abs(dx) > Math.abs(dy)) queueDirection(dx < 0 ? { x: -1, y: 0 } : { x: 1, y: 0 });
    else queueDirection(dy < 0 ? { x: 0, y: -1 } : { x: 0, y: 1 });
  };
  api.debug.listen(canvas, 'pointerdown', state.pointerDownHandler);
  api.debug.listen(canvas, 'pointerup', state.pointerUpHandler);
  state.pointerCanvas = canvas;
  state.pointerReady = true;
  api.debug.addDisposer(function () {
    state.pointerReady = false;
    state.pointerCanvas = null;
    state.pointerStart = null;
  });
}

if (!state.ready) {
  reset();
  state.ready = true;
  api.debug.console.log('Snake Starter Kit ready.');
}
installPointerInput();

if (api.input.wasPressed('Restart') || api.input.wasPressed('KeyR')) reset();
if (api.input.wasPressed('MoveLeft') || api.input.wasPressed('ArrowLeft') || api.input.wasPressed('KeyA')) queueDirection({ x: -1, y: 0 });
if (api.input.wasPressed('MoveRight') || api.input.wasPressed('ArrowRight') || api.input.wasPressed('KeyD')) queueDirection({ x: 1, y: 0 });
if (api.input.wasPressed('MoveUp') || api.input.wasPressed('ArrowUp') || api.input.wasPressed('KeyW')) queueDirection({ x: 0, y: -1 });
if (api.input.wasPressed('MoveDown') || api.input.wasPressed('ArrowDown') || api.input.wasPressed('KeyS')) queueDirection({ x: 0, y: 1 });

if (state.phase === 'playing') {
  state.stepTimer += delta;
  const baseMs = Number(config.stepMs || 145);
  const speedup = Math.min(Number(config.maxSpeedupMs || 72), state.score * Number(config.speedupPerFoodMs || 3));
  const interval = Math.max(Number(config.minStepMs || 70), baseMs - speedup);
  while (state.stepTimer >= interval && state.phase === 'playing') {
    state.stepTimer -= interval;
    stepSnake();
  }
}

draw();
